-- Rifts World Book 3: England - its bestiary and its notable NPCs.
-- 9 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~276-england-creatures-a.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 9 creatures are in' AS assertion, count(*) AS got, 9 AS want
  FROM creatures WHERE slug IN ('dabuggh', 'mantaz-sectle', 'cernun', 'armored-devil-fish', 'crawlies', 'giant-clamp-mouth-dragonfly', 'flash-beetle', 'petal-thing', 'stone-ball-bug');
SELECT 'and 3 of them are playable' AS assertion, count(*) AS got, 3 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('dabuggh', 'mantaz-sectle', 'cernun', 'armored-devil-fish', 'crawlies', 'giant-clamp-mouth-dragonfly', 'flash-beetle', 'petal-thing', 'stone-ball-bug');
SELECT 'the creatures carry 20 attacks' AS assertion, count(*) AS got, 20 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('dabuggh', 'mantaz-sectle', 'cernun', 'armored-devil-fish', 'crawlies', 'giant-clamp-mouth-dragonfly', 'flash-beetle', 'petal-thing', 'stone-ball-bug');

