INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('dabuggh', 'Dabuggh', 'alien humanoid', 'rifts', 1, 'Any, but most are Anarchist or evil predators', '{"IQ":"3D4+6","ME":"2D4+12","MA":"2D6+4","PS":"2D6+12","PP":"2D4+12","PE":"2D4+12","PB":"3D6","Spd":"5D6"}', NULL, NULL, '2D4x10+1D6', '6D6+6', NULL, 'Mega-Damage creature: M.D.C. is 2D4x10 plus 1D6 per level of experience (stored at level one); extra M.D.C. from an exoskeleton roll (30, 100, 200 or 300) and from metamorphosis (+100) is not in the formula. P.S. is supernatural. 30% have wings and fly at 2D4x10 mph. Average Level of Experience (NPC) 1D4+4; uses the Earth and Star Child experience table.', NULL, 10, '{"initiative":1,"strike":1,"dodge":1}', 'Humanoid body: +1 on initiative, +1 to strike, +1 to dodge, +1 to save vs poison, +1 to save vs Horror Factor. Horror Factor 10 applies only once it is recognized for what it is. Attacks per melee come from its Hand to Hand (Expert, or Assassin if evil). Insect form: +100 M.D.C., +20 Spd, +6 P.S., leaps three times as far.', 'R.C.C. Skills: Math: Basic (+15%), Wilderness Survival (+15%), Land Navigation (+10%), Identify Plants & Fruits (+10%), Preserve Food (+10%), Track Animals (+10%), Language: Faerie Speak and two of choice (+20%), Climb (+10%), W.P. five of choice, Hand to Hand: Expert (Assassin if evil). Related Skills: six, plus two at levels 3, 6, 10 and 13: Communication any (+5%), Domestic any (+5%), Espionage any (+5%), Medical First Aid or Holistic Medicine only (+5%), Military any (+10%), Physical any but Acrobatics and Gymnastics, Pilot any but spacecraft and robots (+5%), Rogue any (+5%), Science Math only (+10%), Technical Language, Literacy, Lore, Computer Operation and Writing only (+10%), W.P. any, Wilderness any (+10%); no Electrical, Mechanical or Pilot Related. Secondary Skills: four.', 'Insect metamorphosis: under great stress, anger or in battle it turns into one giant berserk insect or arachnid of its own kind (spiders, scorpions and beetles are common), 7-12 ft (2.1-3.6 m) tall, and stays so until the threat is gone or it drops from exhaustion. In humanoid form it has nightvision 60 ft (18 m), a keen nose (track by smell 60%, scents blood up to a mile/1.6 km off), leaps 10 ft (3 m) up or across and swims 70%. Each also has one to five extra insect traits rolled on the tables of p.55-56: wings (flight 2D4x10 mph), two more arms (+2 attacks), two more legs (30 ft leaps, 50 mph running), a paralysing stinger, web spinning (climb webs 90/80%), wall clinging at half speed, clawed hands and feet (+1D4 M.D., +10% climb), insect strength (+1D4+4 P.S., carries 200 times P.S.); a mouth that tastes and identifies (80%), small mandibles, a toxic or acid spray, or a trail scent (tracked 92%, 42% after one rain); eyes with all-round sight (automatic parry and dodge, +1 to each), polarized sight (95% sun direction), a 30 M.D.C. hard cover, colour and ultraviolet vision, or thermal sight; antennae for scent tracking (75%), identifying smells (90%), remembering a scent (50%), touch identification (70%), temperature and wind (80%), vibration tracking (60%, 1000 ft) or ultrasonic hearing or speech (2000 ft); and an exoskeleton adding 30, 100, 200 or 300 M.D.C. (the heaviest costs 20% of its speed and -10% to prowl, swim and climb).', 'None, though it uses magic weapons and potions and loves magic items.', 'None.', '5 to 7 feet (1.5 to 2.1 m), powerfully built, with tough bronze skin', '180 to 250 lbs (81 to 112.5 kg)', '200 years', 'Almost anywhere humans live; mainly the British Isles, where they came through a rift decades ago (2D6 in most large settlements including New Camelot, at least six all-dabuggh villages of 1D4x100, and a northern island community of 1200 plus 500 D-Bees), with a few colonies in Europe and individuals living among humans as far as the New German Republic', 'None named', 'Sectles above all; humans and other humanoids are rivals and food', 'Optional R.C.C. (p.55-57), printed as an optional player character; uses the Earth and Star Child experience table. Starting money 4D6x100 credits. Ruling D19 gives it a class as well as this row.', 'An arachnid-like D-Bee that passes for a human with one or more insect features (wings, compound eyes, web spinning and the like), often hiding its nature. It drinks the blood and eats the organs of mammals, humans and D-Bees included, and is aggressive, territorial and bent on ruling other intelligent races. Fearless, inventive and swarm-minded, it lives for survival and for wiping out the mantaz sectles, its hated rivals from what is likely the same home world; dabugghs outnumber the sectles two to one. Pronounced Dah bug. A female lays 2D4 eggs each spring, hidden in a cave or cellar, and their numbers are rising fast. Equipment: any human gear it can get (it builds none), typically an energy pistol and rifle, knife and grenades or a vibro-blade.', 'Rifts World Book 3: England p.55-57'),
('mantaz-sectle', 'Mantaz Sectle', 'insectoid', 'rifts', 1, 'Any, but most are Anarchist or good', '{"IQ":"1D6+10","ME":"2D6+12","MA":"2D6+10","PS":"2D6+18","PP":"2D6+12","PE":"2D6+12","PB":"2D6","Spd":"4D6+6"}', NULL, NULL, '3D4x10+2D6', '6D6', NULL, 'Mega-Damage creature: M.D.C. is 3D4x10 plus 2D6 per level of experience (stored at level one). P.S. is supernatural. Twice as fast swinging through trees. Average Level of Experience (NPC) 1D4+3; uses the Earth and Star Child experience table.', NULL, 10, '{"initiative":2,"strike":1,"dodge":1}', '+1 melee action/attack beyond its Hand to Hand (Expert, or Martial Arts at the cost of one Related skill), +2 on initiative, +1 to strike, +1 to dodge, +1 to save vs magic, +2 to save vs poison, +2 to save vs Horror Factor.', 'R.C.C. Skills: Math: Basic (+10%), Wilderness Survival (+20%), Land Navigation (+20%), Holistic Medicine (+5%), Identify Plants & Fruits (+15%), Preserve Food (+15%), Track Animals (+15%), Sing (+15%), Faerie Lore (+10%), Language: Faerie Speak, Dragonese and two of choice (+20%), Climb (+10%), W.P. three ancient and two modern, Hand to Hand: Expert (Martial Arts for one Related skill). Related Skills: four, plus two at levels 3, 7, 11 and 15: Communication any, Domestic any (+5%), Espionage any (+5%), Medical First Aid or Holistic Medicine only (+5%), Military any (+10%), Physical any but Gymnastics, Pilot any but spacecraft and robots (+5%), Rogue any, Science Math, Biology and Botany only (+10%), Technical any (+5%), W.P. any, Wilderness any (+10%); no Electrical, Mechanical or Pilot Related. Secondary Skills: four.', 'Natural mega-damage armor over the whole body. Nightvision 30 ft (9 m); a good nose (track by smell 65%, identify smells 70%); leaps 15 ft (4.6 m) up or across; instinctive climb 90/80%, acrobatics 80%, swim 80% and prowl 60%; a fine singing, whistling and yodeling voice. Faerie-like magic, each usable four times a day at a duration equal to its level: Tongues, Globe of Daylight, Chameleon, See the Invisible, and a 90 ft (27.4 m) magical nightvision. Two scents from the tip of the abdomen: a trail marker it can also spray on a target up to 20 ft (6 m) away, followed at 94% (44% after one rain or washing, gone after two) and smelled up to two miles (3.2 km) away; and alarm scents (danger, attack, death of the sender) that only other sectles notice, at about four miles (6.4 km). Mantaz sectles can ride crawlies, clamp-mouth dragonflies and flash beetles.', 'The five faerie-like spells listed under its abilities; also uses magic weapons, wands, staves and potions. P.P.E. 6D6.', 'None.', '7 to 9 feet (2.1 to 2.7 m)', '200 to 300 lbs (90 to 135 kg)', '180 years', 'Anywhere humans can live, preferring forests and jungles and above all Millennium Trees; mainly the British Isles, where they came through a rift decades ago, with a couple of tiny colonies in France and Africa. Villages of 1D6x10.', 'Can make loyal friends of other intelligent beings; guards the Millennium Trees it lives in', 'Dabugghs; humanoids who attack it in fear of monsters', 'Optional R.C.C. (p.57-58), printed as an optional player character; uses the Earth and Star Child experience table. Starting money 3D6x1000 credits. Ruling D19 gives it a class as well as this row.', 'A praying-mantis-like humanoid, bright green above and yellow, orange or tan beneath, with big yellow or gold eyes. Though it looks like a bug it is warm-blooded, perhaps kin to birds, and is untroubled by its looks. Sectles keep to small villages, hunt animals and leave other thinking beings alone unless provoked, but fight dabugghs on sight. Brave in a fight, gentle with friends, and often shot at by human supremacists for their monstrous look. Pronounced Man Taz Sect tal. Only this one kind of sectle has come to Earth; a female lays 1D4 eggs each spring, high in trees and guarded by 1D4 sectles, and they number about half as many as the dabugghs. Equipment: any human gear it can get, often energy weapons, blades, a neuro-mace or magic items; it seldom wears clothes or armor.', 'Rifts World Book 3: England p.57-58'),
('cernun', 'Cernun', 'alien humanoid', 'rifts', 1, 'Any, but most are Anarchist or evil', '{"IQ":"2D6+8","ME":"2D6+10","MA":"2D6+10","PS":"2D6+8","PP":"2D6+8","PE":"2D6+10","PB":"2D6+2","Spd":"3D6+6"}', NULL, NULL, '1D4x10+8+2D4', '1D6x10+10+PE', '1D4x10+ME', 'Mega-Damage creature: M.D.C. is 1D4x10+8 plus 2D4 per level of experience (stored at level one). P.P.E. is 1D6x10+10 plus the P.E. attribute number, +2D6 per additional level; I.S.P. is 1D4x10 plus the M.E. attribute number, +1D6+1 per additional level. Average Level of Experience (NPC) 1D4+3; uses the Mystic experience table.', NULL, 9, NULL, 'No racial combat bonuses beyond the Mystic O.C.C.''s; Hand to Hand: Expert or Assassin as an NPC. +15% to Escape Artist from being double jointed.', 'Same as the Mystic O.C.C. (Rifts RPG p.85-87), plus Basic Math (+20%).', 'Every cernun has all the powers of the Mystic O.C.C. (Rifts RPG p.85-87). Control Gigantes: telepathic and empathic speech with the giants it calls its children, to 500 ft (153 m) plus 100 ft per level, and full mind control of any with an I.Q. of 6 or less; most travel with one or two. Bio-regeneration: lost fingers, toes, horns and teeth regrow in 48 hours, a hand in 72 hours, an arm in five days, a leg or tail in nine; meditation heals 6D6 M.D. an hour without scars; a lost head cannot be regrown. Also Mega-Damage, nightvision 90 ft (27.4 m), human-like colour vision, leaps 10 ft (3 m) up or across, climb 80/70%, swim 90%, holds its breath four minutes underwater, ambidextrous and double jointed at hip, shoulder and wrist.', 'As the Mystic O.C.C. (Rifts RPG p.85-87); loves magic weapons, wands, staves, potions and items. P.P.E. a little above a typical mystic''s.', 'As the Mystic O.C.C.', '5 to 7 feet (1.5 to 2.1 m)', '200 to 300 lbs (90 to 135 kg)', '380 years', 'Anywhere humans can live, preferring forests and jungles; fewer than a thousand on Rifts Earth, most likely in France, Spain, the British Isles, western Europe, Africa and Atlantis. A ley line nexus in France links to their home dimension.', 'The gigantes it commands', 'None natural; most are evil sorcerers and a danger to good beings', 'Optional R.C.C. (p.58-59), the Cernun Mystic R.C.C., printed as an optional player character; uses the Mystic experience table. Starting money 4D6x1000 credits and 3D6x100 in valuables. Ruling D19 gives it a class as well as this row.', 'Also called the Ram-Horned Serpent Men: supernatural, magic-wielding beings with a thick serpentine trunk ending in a strong tail, thin human arms, muscular legs and big clawed feet; lying flat and unrobed they look like great snakes. The book suggests they visited Earth long ago and were taken for gods by the Celts, whose ram-horned serpent icon they resemble, and that the god Cernunnos may have been one. Most are greedy for wealth, fame and power. The book''s cover shows one driving a gigantes against travelers. Pronounced Seer None. Equipment: a loose robe, gas mask, tinted goggles, a wooden cross and silver dagger, an energy pistol or rifle with 1D4+1 E-clips, and a wand or staff of its choosing; rarely armor, and then light.', 'Rifts World Book 3: England p.58-59'),
('armored-devil-fish', 'Armored Devil Fish', 'monster', 'rifts', 0, 'Considered an evil predator', '{"IQ":"1D4+2","ME":"1D6+10","MA":"2D6","PS":"3D6+20","PP":"2D6+20","PE":"1D6+20","PB":"2D4","Spd":"3D6+32"}', NULL, NULL, '650', '16', NULL, 'Mega-Damage creature; M.D.C. by location: eyes (2) 10 each, large fins (4) 40 each, large tail fin 55, main body 650 (destroying it kills the monster). The tiny, armor-shielded eyes take a called shot at -4 to strike; blinded, it hunts by sonar and smell and fights to the death. Spd is swimming. Low animal intelligence.', NULL, 13, '{"attacks":4,"initiative":1,"strike":5,"dodge":2}', '+1 on initiative, +5 to strike, +2 to dodge, +3 to save vs poison, +2 to save vs magic. Four attacks per melee by bite and head butt, or two body rams.', 'None.', 'Swims and breathes underwater; nightvision 200 ft (60 m); hunts in total darkness by sonar and scent; tracks by smell 70%.', 'None.', 'None.', '20 to 30 feet (6 to 9 m) tall, 30 to 60 feet (9 to 18 m) long and 10 to 20 feet (3 to 6 m) wide, its mouth as wide as its body', '30 tons', '200 years', 'The seas around Scotland and the North Sea, the Mediterranean and the Devil''s Sea near Atlantis, and possibly elsewhere', 'None', 'Everything is prey or a foe', 'None; a sea monster.', 'A giant sea monster of British waters, named for the two devil horns on its huge head and its heavy, horned armor. Having learned that boats carry food, it rams a vessel with its head and upper body and eats whoever falls in; it has been seen to surface and swallow a rowboat whole. Languages unknown. Value: little; its nine big plates fetch about 2000 credits each as ship plating, and its flesh is good eating.', 'Rifts World Book 3: England p.60'),
('crawlies', 'Crawlies', 'insectoid', 'rifts', 0, 'Considered Anarchist; a predatory insect', '{"IQ":"1D4","ME":"1D6+3","MA":"1D6","PS":"1D6+20","PP":"1D6+10","PE":"1D6+20","PB":"1D6","Spd":"1D6+20"}', NULL, NULL, '200', '4', NULL, 'Mega-Damage creature; M.D.C. by location: eyes (2) 12 each, armored top abdomen 180, abdomen underside 60, legs (24) 20 each, large antennae (2) 30 each, small antennae (2) 8 each, head 80, main body 200. Destroying the main body or the soft underside kills it. Eyes and antennae take a called shot at -3 to strike; with both eyes gone it hunts by antennae, loses its dodge bonus and halves its other combat bonuses. Spd is crawling, half that digging; it cannot fly. Low animal I.Q.', NULL, 8, '{"attacks":3,"initiative":1,"strike":3,"parry":3,"dodge":1}', '+1 on initiative, +3 to strike and parry with its tail and hindquarters, +1 to dodge, +8 to save vs poison, +2 to save vs magic.', 'None.', 'Armored M.D.C. plating; nightvision 200 ft (60 m); feelers with a superb sense of touch let it hunt in the dark; sharp hearing. Skills: dig 80%, track by smell 80%, identify smells 80%, climb 90%, swim 40%, prowl 40%. Turned over, it needs 1D4 melee rounds to right itself, its weak belly exposed meanwhile (explosives rolled under it work well too). Clicks its armor plates as an alarm when its burrow is invaded.', 'None.', 'None.', 'Three feet (0.9 m) tall and 10 to 15 feet (3 to 4.6 m) long', '900 lbs (405 kg)', '8 years', 'Rocky, hilly and mountainous land, occasionally forest; almost only Scotland and the mountains of Europe and Africa', 'None', 'Humanoids, faerie folk and animals, especially slow ground creatures; it eats almost anything living under 12 feet (3.6 m)', 'None; an alien animal. Only mantaz sectles and simvan monster riders can ride one.', 'Also called Hill Beetles: centipede-like insects from another dimension, the least aggressive of the British alien bugs and quick to panic, though one cornered fights to the death. They eat carrion, refuse, eggs and slow animals, humanoids among them, raid trappers'' snares, and dig pits up to 12 ft (3.6 m) deep as traps, a colony of 4D6 living in shallow burrows nearby with 1D4 waiting in ambush. Value: little; the plates are too heavy for armor, the spray glands sell for about 500 credits each, and the meat is edible. Too dim and erratic to train as mounts.', 'Rifts World Book 3: England p.60-61'),
('giant-clamp-mouth-dragonfly', 'Giant Clamp-Mouth Dragonfly', 'insectoid', 'rifts', 0, 'Considered Anarchist or evil; a predatory insect', '{"IQ":"1D4","ME":"1D6+8","MA":"1D6","PS":"1D6+20","PP":"1D6+10","PE":"1D6+14","PB":"1D4","Spd":"4D6"}', NULL, NULL, '450', '10', NULL, 'Mega-Damage creature; M.D.C. by location: wings (10) 10 each, eyes (2) 12 each or 24 each, rear head plate 65, head 250, mandibles (3) 100 each, main body 450 (destroying it kills the monster). Losing four front wings grounds it; losing the four back wings cuts speed by 25% and halves its dodge as the body drags. Eyes take a called shot at -3 to strike; blinded, it loses its initiative and dodge bonuses but hunts by smell. Spd 4D6 crawling, 2D4x10 flying. Low animal I.Q.', NULL, 13, '{"attacks":4,"initiative":2,"strike":5,"dodge":5}', '+2 on initiative, +5 to strike, +5 automatic dodge, +6 to save vs poison and magic.', 'None.', 'Armored M.D.C. plating. Sees in the dark to 120 ft (36.6 m); tracks by smell 80%; flies; climb 30%, swim 60%, prowl 50%. A grounded one still slithers along and fights. In a fight it gives off a scent that draws 1D4 more hungry dragonflies or flash beetles. When prey is clamped in its jaws a clear film drops over its eyes to shield them. It shuns anything about 20 ft (6 m) or bigger and outflies large robots. A rider on its back is dragged through branches (5D6 S.D.C. a melee, no attacks) and must roll under P.S. on percentile dice to hold on; a fall does 6D6 more and costs initiative and two attacks; M.D.C. armor cuts both to a quarter. A shot just behind the eyes, through the 65 M.D.C. rear head plate, kills it without spoiling the armor.', 'None.', 'None.', '20 to 50 feet (6 to 15.2 m) long, its wingspan a third of its length', '1000 to 2000 lbs (450 to 900 kg)', '15 years', 'Forests, especially around Millennium Trees, ley lines, nexuses, faerie mounds and other places of magic; common in the British Isles and much of western Europe and Africa', 'None, though its battle scent summons other dragonflies and flash beetles', 'Humanoids, faerie folk, gryphons, peryton and animals; it eats almost any living thing under 15 feet (4.6 m)', 'None; an alien predator. Only mantaz sectles and simvan monster riders can ride one.', 'A serpent-bodied alien dragonfly with four pairs of wings, M.D.C. armor and enormous mandibles that seize prey and carry it off; a combined P.S. of 40 is needed to pry them apart. The true danger is the small inner mouth that eats the held victim alive. It takes only living prey and is drawn to P.P.E. Daring woodsmen hunt it for its plates. Clicks its mandibles but has no language. Value: the eight plates behind the head sell at 1200 credits each, and three large plates make a suit of human-sized armor of 65 M.D.C. (25 lbs/11.4 kg, -5% to prowl) worth 34,000 credits. Too stupid and wild to train as a mount.', 'Rifts World Book 3: England p.61-63'),
('flash-beetle', 'Flash Beetle', 'insectoid', 'rifts', 0, 'Considered Anarchist or evil; a predatory insect', '{"IQ":"1D4","ME":"1D6+8","MA":"1D6","PS":"1D6+24","PP":"1D6+12","PE":"1D6+14","PB":"1D6","Spd":"2D6+24"}', NULL, NULL, '300', '4', NULL, 'Mega-Damage creature; M.D.C. by location: wings (4) 25 each, wing casings (2) 150 each, eyes (2) 20 each, armored top abdomen 220, abdomen underside 90, legs (6) 50 each, antennae (2) 15 each, head 130, main body 300. Destroying the main body or the soft underside kills it. Losing a pair of wings grounds it; losing three legs halves its running speed. Eyes and antennae take a called shot at -2 to strike; with both eyes gone it hunts by antennae, loses its dodge bonus and halves its other combat bonuses. Spd 2D6+24 crawling, 1D4x10+10 flying. Low animal I.Q.', NULL, 10, '{"attacks":3,"initiative":3,"strike":4,"parry":4,"dodge":4}', '+3 on initiative, +5 to strike with the energy beam, +4 to strike, parry and dodge physical attacks, +4 to save vs poison and magic.', 'None.', 'Armored M.D.C. plating; nightvision 120 ft (36.6 m); sharp hearing; identify smells 88% and track by smell 88%; flies; climb 80%, swim 40%, prowl 40%. In a fight it gives off a scent that may draw 1D4 hungry flash beetles and 1D4 clamp-mouth dragonflies.', 'None.', 'None.', 'Eight feet (2.4 m) tall and 15 to 20 feet (4.6 to 6 m) long, its wingspan half its length', '2000 lbs (900 kg)', '8 years', 'Almost anywhere, forest, grassland or mountain, often near Millennium Trees, ley lines, nexuses, faerie mounds and other places of magic; common in the British Isles and much of Europe and Africa', 'None, though its battle scent summons others of its kind and clamp-mouth dragonflies', 'Humanoids, faerie folk and animals, especially slow ground creatures; it eats almost anything living under 12 feet (3.6 m)', 'None; an alien predator. Only mantaz sectles and simvan monster riders can ride one.', 'An alien beetle named for the laser-like beam it shoots from its abdomen. It eats only live prey, S.D.C. or M.D.C., and is drawn to places of magic and the use of mystic energy. A lone hunter, less aggressive than the clamp-mouth dragonfly, though now and then 1D4+1 hunt together. Clicks its legs but has no language. Value: none; its plates are too brittle for armor, and it is too stupid and wild to train as a mount.', 'Rifts World Book 3: England p.63'),
('petal-thing', 'Petal Thing', 'alien', 'rifts', 0, 'Considered an evil predator; at best Unprincipled or Anarchist', '{"IQ":"2D6+2","ME":"1D6+16","MA":"2D6+10","PS":"1D6+12","PP":"1D6+12","PE":"1D6+12","PB":"2D6+18","Spd":"6D6+22"}', NULL, NULL, '140', '4', '4D6x10', 'Mega-Damage creature; M.D.C. by location: eye crystal (true head) 100, large fins (2) 70 each, leafy tentacles (4) 40 each, large leafy wings (2) 90 each, bony petals (4) 120 each, false head 240, main bulbous body 140 (destroying it kills the monster). The crystal takes a called shot at -2 to strike and may be shielded by its tentacles; destroying it blinds the creature and halves its psionics. Spd 6D6+22 flying in bursts of up to six minutes; it usually hovers at 6 to 22. P.S. and P.E. are supernatural. Low humanoid intelligence.', NULL, 11, '{"attacks":4,"initiative":1,"strike":3,"parry":3,"dodge":1}', 'Horror Factor 11 when it lunges to attack. +1 on initiative, +3 to strike and parry with its tail and hindquarters (as printed), +1 to dodge, +8 to save vs poison, +2 to save vs magic. Four physical or four psionic attacks per melee.', 'None.', 'Hovers and flies, darting forward, back, up or down at bullet speed with a sweep of its wings; swims underwater at half its flying speed (80%). Armored bony petals; nightvision 200 ft (60 m); finds prey in the dark with its tentacles; good hearing; senses the P.P.E. of living things and tracks by it (68%). Its slow, swaying motion hypnotizes onlookers: a lulled victim loses initiative, gets no parry or dodge against its opening attack, loses one melee action and has its combat bonuses halved for that first melee round. May speak empathically.', 'None.', 'I.S.P. 4D6x10, powers equal to a sixth level psychic: Mind Block, Empathy, Empathic Transmission, Pyrokinesis, Mind Bolt, Mentally Possess Others, Resist Fatigue and Bio-Regeneration (2D6 M.D.), plus its special hypnotic movement.', 'Body bulb three feet (0.9 m) tall and four feet (1.2 m) wide; 12 to 18 feet (3.6 to 5.5 m) tall overall with petals and top fin', '300 lbs (135 kg)', '120 years', 'Forests and jungles of most of Europe, Asia and parts of Africa; not in the Americas or Australia', 'Simvan monster riders, who resist its hypnosis, may win it over as a mount or partner', 'Everything is prey or a foe', 'None. The book does not recommend it as a player character but leaves it to the G.M., since it is clever enough to play; it lives to hunt and kill and cares nothing for money or magic.', 'Neither plant nor insect, though it looks like both: a soft white or pastel body splashed with blue, violet or red, with a fin above and below. In front is a false head like a demonic snapdragon, with a great jaw, yellow teeth and four glossy black eye-like bulbs, which draws attackers'' fire; its real head is the emerald crystal above it. Four small leafy tentacles serve as clumsy hands, two big leaf-like wings drive it, and four hard bony petals underneath scoop or ram prey like a train''s cow-catcher. It hangs among the branches, lulls prey with its swaying, then strikes. A psionic hunter that feeds on P.P.E., like a psi-stalker, it prefers to kill for the death surge and for the pleasure of it. Value: worth something only as a guard or attack beast.', 'Rifts World Book 3: England p.64-65'),
('stone-ball-bug', 'Stone Ball Bug', 'insectoid', 'rifts', 0, 'Considered Anarchist', '{"IQ":"1D4","ME":"1D6+4","MA":"1D6","PS":"1D6","PP":"1D6","PE":"1D6+20","PB":"1D6","Spd":"1D6+2"}', NULL, NULL, '60', '12', NULL, 'Mega-Damage creature; M.D.C. by location: legs (12) 1 each, front pincer arms (2) 3 each, main body 60 (destroying it kills the critter). Spd is crawling. Low animal I.Q.', NULL, 0, '{"attacks":0}', 'No combat: it makes no attacks. +10 to save vs poison, +5 to save vs magic and psionic attack.', 'None.', 'Armored M.D.C. shell it retracts its legs into when threatened; nightvision 100 ft (30.5 m); finds its food in the dark by touch. Skills: identify smells 60%, track by smell 60%, climb 60%, swim 40%, prowl 40%. Seems not to need air, and can walk along a river bottom for hours.', 'None.', 'None.', 'About the size of a bowling ball', '8 to 14 lbs (3.6 to 6.4 kg)', '80 years', 'Rubbish dumps, graveyards, slaughterhouses, village and town alleys, and forests', 'None', 'None', 'None; a harmless alien scavenger.', 'A harmless alien scavenger shaped like a stone sphere on twelve tiny legs, with two small pincer arms, that eats dead animals and rotting food. Country folk bowl with them, keep them as pets or living garbage disposals, and count them lucky, likely because they clear away what breeds disease; herbalists grind the legs of dead ones into remedies against poison and stomach complaints. No language. Value: about 20 credits as a pet in the British Isles, perhaps ten times that where none have been seen.', 'Rifts World Book 3: England p.65-66');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'dabuggh', 'Insect form bite or sting', '3D6', 1, NULL, 'Mandibles or stinger, only while metamorphosed into its giant insect form.', 0),
('creature', 'dabuggh', 'Stinger tail', '2D6', 1, NULL, 'Only for a dabuggh that rolled the stinger trait (Features 51-60). Save vs poison or paralysed for 1D4 melee rounds; stings are cumulative.', 1),
('creature', 'dabuggh', 'Small mandibles bite', '4D6', 0, NULL, 'S.D.C. Only with the mandibles trait (Insect Mouth 21-40).', 2),
